        $q=mb_substr(trim((string)($filters['q']??'')),0,120);if($q!==''){$where[]='(s.slug LIKE ? OR EXISTS(SELECT 1 FROM survey_translations st WHERE st.survey_id=s.id AND st.title LIKE ?))';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}
        $status=(string)($filters['status']??'all');if(in_array($status,['draft','scheduled','published','closed'],true)){$where[]='s.status=?';$params[]=$status;}
        $facility=max(0,(int)($filters['facility_id']??0));if($facility){$where[]='EXISTS(SELECT 1 FROM survey_facilities sc WHERE sc.survey_id=s.id AND sc.facility_id=?)';$params[]=$facility;}
        $scopeSql=$this->scopeSql('s',$scope);$where[]=$scopeSql['sql'];$params=array_merge($params,$scopeSql['params']);$clause=implode(' AND ',$where);
        $count=$this->db->prepare('SELECT COUNT(*) FROM surveys s WHERE '.$clause);$count->execute($params);$total=(int)$count->fetchColumn();$offset=($page-1)*$perPage;
        $sql='SELECT s.*,COALESCE(t.title,s.slug) title,(SELECT COUNT(*) FROM survey_questions q WHERE q.survey_id=s.id) question_count,(SELECT COUNT(*) FROM survey_responses r WHERE r.survey_id=s.id AND r.status="completed") response_count,(SELECT COUNT(*) FROM survey_facilities c WHERE c.survey_id=s.id) facility_count FROM surveys s LEFT JOIN survey_translations t ON t.survey_id=s.id AND t.locale=(SELECT locale FROM languages WHERE enabled=1 ORDER BY is_default DESC,sort_order,id LIMIT 1) WHERE '.$clause.' ORDER BY s.updated_at DESC,s.id DESC LIMIT '.$perPage.' OFFSET '.$offset;
        $statement=$this->db->prepare($sql);$statement->execute($params);$items=$statement->fetchAll();foreach($items as&$item)$item['effective_status']=$this->effectiveStatus($item);unset($item);
        return['items'=>$items,'pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/$perPage)),'total'=>$total,'per_page'=>$perPage],'summary'=>$this->summary($scope)];
    }

