    public function responses(int$id,array$filters,?array$scope,int$page=1,int$perPage=30):array
    {
        $this->survey($id,$scope);$page=max(1,$page);$where=['r.survey_id=?'];$params=[$id];$status=(string)($filters['status']??'all');if(in_array($status,['started','completed','abandoned','disqualified'],true)){$where[]='r.status=?';$params[]=$status;}$facility=max(0,(int)($filters['facility_id']??0));if($facility){$where[]='r.facility_id=?';$params[]=$facility;}$from=$this->date($filters['from']??null,'Invalid start date.',true);if($from){$where[]='r.started_at>=?';$params[]=$from;}$to=$this->date($filters['to']??null,'Invalid end date.',true);if($to){$where[]='r.started_at<=?';$params[]=$to;}$clause=implode(' AND ',$where);$count=$this->db->prepare('SELECT COUNT(*) FROM survey_responses r WHERE '.$clause);$count->execute($params);$total=(int)$count->fetchColumn();$statement=$this->db->prepare('SELECT r.*,c.city_slug,c.facility_slug,COALESCE(ct.name,c.facility_slug) facility_name FROM survey_responses r LEFT JOIN facilities c ON c.id=r.facility_id LEFT JOIN facility_translations ct ON ct.facility_id=c.id AND ct.locale=r.locale WHERE '.$clause.' ORDER BY r.started_at DESC LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage));$statement->execute($params);return['items'=>$statement->fetchAll(),'pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/$perPage)),'total'=>$total]];
