    public function response(int$surveyId,string$uid,?array$scope):array
    {
        $detail=$this->detail($surveyId,$scope);$statement=$this->db->prepare('SELECT r.*,c.city_slug,c.facility_slug FROM survey_responses r LEFT JOIN facilities c ON c.id=r.facility_id WHERE r.survey_id=? AND r.uid=? LIMIT 1');$statement->execute([$surveyId,$uid]);$response=$statement->fetch();if(!$response)throw new RuntimeException('Survey response was not found.',404);$labels=[];foreach($detail['pages']as$page)foreach($page['questions']as$question){$copy=$question['translations'][$response['locale']]??$question['translations'][$this->defaultLocale()]??reset($question['translations']);$labels[(int)$question['id']]=['label'=>$copy['label']??$question['uid'],'type'=>$question['type']];}$answers=$this->db->prepare('SELECT question_id,value,text_value,numeric_value FROM survey_answers WHERE response_id=? ORDER BY id');$answers->execute([$response['id']]);$response['answers']=[];foreach($answers->fetchAll()as$answer)if(isset($labels[(int)$answer['question_id']]))$response['answers'][]=$labels[(int)$answer['question_id']]+['value'=>$this->json($answer['value'],$answer['text_value']),'text_value'=>$answer['text_value'],'numeric_value'=>$answer['numeric_value']];return$response;
