    public function exportRows(int$id,?array$scope):array
    {
        $detail=$this->detail($id,$scope);$questions=[];foreach($detail['pages']as$page)foreach($page['questions']as$question){$copy=$question['translations'][$this->defaultLocale()]??reset($question['translations']);$questions[(int)$question['id']]=['uid'=>$question['uid'],'label'=>$copy['label']??$question['uid']];}$statement=$this->db->prepare('SELECT r.*,c.city_slug,c.facility_slug FROM survey_responses r LEFT JOIN facilities c ON c.id=r.facility_id WHERE r.survey_id=? ORDER BY r.started_at');$statement->execute([$id]);$rows=[];foreach($statement->fetchAll()as$response){$row=['Response ID'=>$response['uid'],'Status'=>$response['status'],'Language'=>$response['locale'],'Facility'=>trim((string)$response['city_slug'].' / '.(string)$response['facility_slug']),'Started'=>$response['started_at'],'Completed'=>$response['completed_at'],'Name'=>$response['respondent_name'],'Email'=>$response['respondent_email']];$answers=$this->db->prepare('SELECT question_id,text_value FROM survey_answers WHERE response_id=?');$answers->execute([$response['id']]);foreach($questions as$question)$row[$question['label']]='';foreach($answers->fetchAll()as$answer)if(isset($questions[(int)$answer['question_id']]))$row[$questions[(int)$answer['question_id']]['label']]=$answer['text_value'];$rows[]=$row;}return['survey'=>$detail,'rows'=>$rows];
    }

    public function maintain(int$limit=500):array
    {
        $opened=$this->db->exec("UPDATE surveys SET status='published',published_at=COALESCE(published_at,NOW()),updated_at=NOW() WHERE status='scheduled' AND opens_at<=NOW() AND (closes_at IS NULL OR closes_at>NOW())");$closed=$this->db->exec("UPDATE surveys SET status='closed',updated_at=NOW() WHERE status IN ('scheduled','published') AND closes_at IS NOT NULL AND closes_at<=NOW()");$surveys=$this->db->query('SELECT id,retention_days,anonymize_after_days FROM surveys')->fetchAll();$anonymized=0;$deleted=0;foreach($surveys as$survey){$cut=(new DateTimeImmutable())->modify('-'.(int)$survey['anonymize_after_days'].' days')->format('Y-m-d H:i:s');$statement=$this->db->prepare('UPDATE survey_responses SET respondent_name=NULL,respondent_email=NULL,token_hash=NULL,visitor_hash=NULL,metadata=JSON_OBJECT(),anonymized_at=NOW() WHERE survey_id=? AND status="completed" AND anonymized_at IS NULL AND completed_at<? LIMIT '.$limit);$statement->execute([$survey['id'],$cut]);$anonymized+=$statement->rowCount();$retention=(new DateTimeImmutable())->modify('-'.(int)$survey['retention_days'].' days')->format('Y-m-d H:i:s');$ids=$this->ids('SELECT id FROM survey_responses WHERE survey_id=? AND COALESCE(completed_at,started_at)<? LIMIT '.$limit,[$survey['id'],$retention]);if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$this->db->prepare('DELETE FROM survey_answers WHERE response_id IN ('.$marks.')')->execute($ids);$this->db->prepare('DELETE FROM survey_responses WHERE id IN ('.$marks.')')->execute($ids);$deleted+=count($ids);}}return['ok'=>true,'opened'=>$opened,'closed'=>$closed,'anonymized'=>$anonymized,'deleted'=>$deleted];
    }

    public function visitorHash(string$ip,string$userAgent):string{return hash_hmac('sha256',$ip.'|'.mb_substr($userAgent,0,300),$this->secret?:'sensecms-surveys');}
    public function recentCompletedCount(?array$scope):int{$scopeSql=$this->scopeSql('s',$scope);$statement=$this->db->prepare('SELECT COUNT(*) FROM survey_responses r INNER JOIN surveys s ON s.id=r.survey_id WHERE r.status="completed" AND r.completed_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR) AND '.$scopeSql['sql']);$statement->execute($scopeSql['params']);return(int)$statement->fetchColumn();}

